package com.mediconnect.service;
import com.mediconnect.entity.*;import com.mediconnect.repository.*;import jakarta.transaction.Transactional;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@Service public class AppointmentService{
 private final AppointmentRepository appointments;private final AppointmentRescheduleRepository reschedules;private final AvailabilityRepository availability;private final UserRepository users;private final DepartmentRepository departments;private final NotificationRepository notifications;private final AuditLogRepository audits;
 public AppointmentService(AppointmentRepository a,AppointmentRescheduleRepository r,AvailabilityRepository v,UserRepository u,DepartmentRepository d,NotificationRepository n,AuditLogRepository al){appointments=a;reschedules=r;availability=v;users=u;departments=d;notifications=n;audits=al;}
 public List<Appointment> list(User user,String status){if(user.getRole()==Role.PLATFORM_SUPER_ADMIN)throw forbidden("Platform administrators do not have clinical record access");List<Appointment>r=switch(user.getRole()){case PATIENT->appointments.findByPatientIdOrderByAppointmentDateAscAppointmentTimeAsc(user.getId());case DOCTOR->appointments.findByDoctorIdOrderByAppointmentDateAscAppointmentTimeAsc(user.getId());case ADMIN->appointments.findAllByHospitalIdOrderByAppointmentDateAscAppointmentTimeAsc(user.getHospital().getId());case PLATFORM_SUPER_ADMIN->List.of();};if(status==null||status.isBlank())return r;AppointmentStatus st=parseStatus(status);return r.stream().filter(a->a.getStatus()==st).toList();}
 @Transactional public Appointment book(User patient,Map<String,Object>b){Long doctorId=longVal(b.get("doctor"));LocalDate date=parseDate(b.get("appointmentDate"));LocalTime time=parseTime(b.get("appointmentTime"));String reason=s(b,"reason");if(doctorId==null||date==null||time==null||reason.isBlank())throw bad("Doctor, date, time, and reason are required");if(date.isBefore(LocalDate.now()))throw bad("Appointment date cannot be in the past");User doctor=users.findById(doctorId).orElseThrow(()->notFound("Doctor not found"));if(doctor.getRole()!=Role.DOCTOR||!doctor.isApproved()||!doctor.isActive()||!sameHospital(patient,doctor))throw bad("Doctor is not available in this hospital");Availability slot=availability.lockAvailableSlot(doctorId,date,time).filter(x->sameHospital(patient,x.getHospital())).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"This time slot is unavailable"));if(appointments.existsByDoctorIdAndAppointmentDateAndAppointmentTimeAndStatusIn(doctorId,date,time,List.of(AppointmentStatus.PENDING,AppointmentStatus.CONFIRMED)))throw new ResponseStatusException(HttpStatus.CONFLICT,"This slot has just been booked");Appointment a=new Appointment();a.setHospital(patient.getHospital());a.setPatient(patient);a.setDoctor(doctor);a.setAppointmentDate(date);a.setAppointmentTime(time);a.setReason(reason);if(b.get("symptoms")!=null)a.setSymptoms(s(b,"symptoms"));Long depId=longVal(b.get("department"));if(depId!=null){Department department=departments.findById(depId).orElseThrow(()->bad("Department is unavailable"));if(!sameHospital(patient,department.getHospital()))throw bad("Department is unavailable");a.setDepartment(department);}a=appointments.save(a);slot.setAvailable(false);availability.save(slot);notify(doctor,"New appointment","New appointment with "+patient.getName()+" on "+date+" at "+time,"APPOINTMENT");notify(patient,"Appointment booked","Your appointment with "+doctor.getName()+" is scheduled for "+date+" at "+time,"APPOINTMENT");audit(patient,"BOOK_APPOINTMENT","Appointment",a.getId(),"Booked with "+doctor.getName());return a;}
 @Transactional public Appointment reschedule(Long id,User actor,Map<String,Object> body){Appointment a=get(id);if(actor.getRole()==Role.PLATFORM_SUPER_ADMIN||!sameHospital(actor,a.getHospital())||actor.getRole()==Role.DOCTOR&&!a.getDoctor().getId().equals(actor.getId()))throw forbidden("Not authorized to reschedule this appointment");if(actor.getRole()==Role.PATIENT&&!a.getPatient().getId().equals(actor.getId()))throw forbidden("Not your appointment");if(a.getStatus()!=AppointmentStatus.PENDING&&a.getStatus()!=AppointmentStatus.CONFIRMED)throw bad("Only pending or confirmed appointments can be rescheduled");LocalDate date=parseDate(body.get("appointmentDate"));LocalTime time=parseTime(body.get("appointmentTime"));if(date==null||time==null||date.isBefore(LocalDate.now()))throw bad("Choose a valid future appointment date and time");if(date.equals(a.getAppointmentDate())&&time.equals(a.getAppointmentTime()))return a;Availability next=availability.lockAvailableSlot(a.getDoctor().getId(),date,time).filter(slot->sameHospital(actor,slot.getHospital())).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"This time slot is unavailable"));if(appointments.existsByDoctorIdAndAppointmentDateAndAppointmentTimeAndStatusIn(a.getDoctor().getId(),date,time,List.of(AppointmentStatus.PENDING,AppointmentStatus.CONFIRMED)))throw new ResponseStatusException(HttpStatus.CONFLICT,"This slot has just been booked");AppointmentReschedule history=new AppointmentReschedule();history.setHospital(a.getHospital());history.setAppointment(a);history.setActor(actor);history.setOldDate(a.getAppointmentDate());history.setOldTime(a.getAppointmentTime());history.setNewDate(date);history.setNewTime(time);reschedules.save(history);availability.findByDoctorIdAndDateAndStartTime(a.getDoctor().getId(),a.getAppointmentDate(),a.getAppointmentTime()).ifPresent(old->{old.setAvailable(true);availability.save(old);});a.setAppointmentDate(date);a.setAppointmentTime(time);Appointment saved=appointments.save(a);next.setAvailable(false);availability.save(next);notify(a.getDoctor(),"Appointment rescheduled","An appointment was moved to "+date+" at "+time,"APPOINTMENT");notify(a.getPatient(),"Appointment rescheduled","Your appointment was moved to "+date+" at "+time,"APPOINTMENT");audit(actor,"RESCHEDULE_APPOINTMENT","Appointment",a.getId(),"Moved from "+history.getOldDate()+" "+history.getOldTime()+" to "+date+" "+time);return saved;}
 public List<AppointmentReschedule> rescheduleHistory(Long id,User actor){Appointment a=get(id);boolean allowed=actor.getRole()!=Role.PLATFORM_SUPER_ADMIN&&sameHospital(actor,a.getHospital())&&(actor.getRole()==Role.ADMIN||actor.getRole()==Role.DOCTOR&&a.getDoctor().getId().equals(actor.getId())||actor.getRole()==Role.PATIENT&&a.getPatient().getId().equals(actor.getId()));if(!allowed)throw forbidden("Not authorized to view this appointment history");return reschedules.findByAppointmentIdOrderByCreatedAtAsc(id);}
 @Transactional public Appointment status(Long id,User actor,Map<String,Object>body){Appointment a=get(id);if(actor.getRole()==Role.PLATFORM_SUPER_ADMIN||!sameHospital(actor,a.getHospital()))throw forbidden("Appointment is outside your hospital");if(actor.getRole()==Role.DOCTOR&&!a.getDoctor().getId().equals(actor.getId()))throw forbidden("Not your appointment");if(actor.getRole()==Role.PATIENT)throw forbidden("Patients cannot change appointment status");AppointmentStatus next=parseStatus(s(body,"status"));if(next==AppointmentStatus.CANCELLED)return cancelInternal(a,s(body,"consultationNotes"),actor);boolean allowed=a.getStatus()==AppointmentStatus.PENDING&&next==AppointmentStatus.CONFIRMED||a.getStatus()==AppointmentStatus.CONFIRMED&&(next==AppointmentStatus.COMPLETED||next==AppointmentStatus.NO_SHOW);if(!allowed)throw bad("Invalid appointment status transition");a.setStatus(next);if(body.get("consultationNotes")!=null)a.setConsultationNotes(s(body,"consultationNotes"));Appointment saved=appointments.save(a);notify(a.getPatient(),"Appointment updated","Appointment with "+a.getDoctor().getName()+" is now "+next.name().replace('_',' '),"APPOINTMENT");audit(actor,"UPDATE_APPOINTMENT","Appointment",a.getId(),"Status: "+next);return saved;}
 @Transactional public Appointment cancel(Long id,User actor,Map<String,Object>body){Appointment a=get(id);if(actor.getRole()==Role.PLATFORM_SUPER_ADMIN||!sameHospital(actor,a.getHospital()))throw forbidden("Appointment is outside your hospital");if(actor.getRole()==Role.PATIENT&&!a.getPatient().getId().equals(actor.getId()))throw forbidden("Not your appointment");if(actor.getRole()==Role.DOCTOR&&!a.getDoctor().getId().equals(actor.getId())&&actor.getRole()!=Role.ADMIN)throw forbidden("Not your appointment");return cancelInternal(a,s(body,"reason"),actor);}
 private Appointment cancelInternal(Appointment a,String reason,User actor){if(a.getStatus()==AppointmentStatus.CANCELLED)return a;if(a.getStatus()!=AppointmentStatus.PENDING&&a.getStatus()!=AppointmentStatus.CONFIRMED)throw bad("Only pending or confirmed appointments can be cancelled");a.setStatus(AppointmentStatus.CANCELLED);a.setCancellationReason(reason.isBlank()?"Cancelled":reason);availability.findByDoctorIdAndDateAndStartTime(a.getDoctor().getId(),a.getAppointmentDate(),a.getAppointmentTime()).ifPresent(s->{s.setAvailable(true);availability.save(s);});Appointment saved=appointments.save(a);User other=actor.getId().equals(a.getPatient().getId())?a.getDoctor():a.getPatient();notify(other,"Appointment cancelled","Appointment on "+a.getAppointmentDate()+" at "+a.getAppointmentTime()+" was cancelled.","APPOINTMENT");audit(actor,"CANCEL_APPOINTMENT","Appointment",a.getId(),reason);return saved;}
 private void notify(User u,String title,String msg,String type){Notification notification=new Notification(u,title,msg,type);notification.setHospital(u.getHospital());notifications.save(notification);}private void audit(User u,String action,String type,Long id,String details){AuditLog log=new AuditLog(u,action,type,id,details);log.setHospital(u.getHospital());audits.save(log);}
 private Appointment get(Long id){return appointments.findById(id).orElseThrow(()->notFound("Appointment not found"));}private static String s(Map<String,Object>b,String k){Object v=b.get(k);return v==null?"":String.valueOf(v).trim();}private static Long longVal(Object x){try{return x==null?null:Long.valueOf(String.valueOf(x));}catch(Exception e){return null;}}private static LocalDate parseDate(Object x){try{return x==null?null:LocalDate.parse(String.valueOf(x));}catch(Exception e){return null;}}private static LocalTime parseTime(Object x){try{return x==null?null:LocalTime.parse(String.valueOf(x));}catch(Exception e){return null;}}private static AppointmentStatus parseStatus(String s){try{return AppointmentStatus.valueOf(s.toUpperCase());}catch(Exception e){throw bad("Invalid appointment status");}}private static boolean sameHospital(User a,User b){return a.getHospital()!=null&&b.getHospital()!=null&&a.getHospital().getId().equals(b.getHospital().getId());}private static boolean sameHospital(User user,Hospital hospital){return user.getHospital()!=null&&hospital!=null&&user.getHospital().getId().equals(hospital.getId());}private static boolean sameHospital(User user,Department d){return d!=null&&sameHospital(user,d.getHospital());}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}private static ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}
}
